export const HADITHS: HadithItem[] = [
  { id: 1, text: 'عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ: " إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوْ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إلَى مَا هَاجَرَ إلَيْهِ". رَوَاهُ إِمَامَا الْمُحَدِّثِينَ أَبُو عَبْدِ اللهِ مُحَمَّدُ بنُ إِسْمَاعِيل بن إِبْرَاهِيم بن الْمُغِيرَة بن بَرْدِزبَه الْبُخَارِيُّ الْجُعْفِيُّ رَضِيَ اللهُ عَنْهُمَا فِي "صَحِيحَيْهِمَا" اللذَينِ هُمَا أَصَحُّ الْكُتُبِ الْمُصَنَّفَةِ.', narrator: 'عمر بن الخطاب رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 2, text: 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْت رَسُولَ اللَّهِ صلى الله عليه و سلم يَقُولُ: " بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إلَهَ إلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ". .', narrator: 'عبد الله بن عمر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 3, text: 'عَنْ أُمِّ الْمُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قَالَ: رَسُولُ اللَّهِ صلى الله عليه و سلم "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ وَفِي رِوَايَةٍ لِمُسْلِمٍ: مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ".', narrator: 'عائشة رضي الله عنها', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 4, text: 'عَنْ أَبِي عَبْدِ اللَّهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْت رَسُولَ اللَّهِ صلى الله عليه و سلم يَقُولُ: "إنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنْ النَّاسِ، فَمَنْ اتَّقَى الشُّبُهَاتِ فَقْد اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ". .', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 5, text: 'عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ: "الدِّينُ النَّصِيحَةُ." قُلْنَا: لِمَنْ؟ قَالَ: "لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ."', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 6, text: 'عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إلَهَ إلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ؛ فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى" .', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 7, text: 'عَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْت رَسُولَ اللَّهِ صلى الله عليه و سلم يَقُولُ: "مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ ".', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 8, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "إنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ تَعَالَى: "يَا أَيُّهَا الرُّسُلُ كُلُوا مِنْ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا"، وَقَالَ تَعَالَى: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ" ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إلَى السَّمَاءِ: يَا رَبِّ! يَا رَبِّ! وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِّيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لَهُ؟".', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 9, text: 'عَنْ أَبِي مُحَمَّدٍ الْحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ سِبْطِ رَسُولِ اللَّهِ صلى الله عليه و سلم وَرَيْحَانَتِهِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: حَفِظْت مِنْ رَسُولِ اللَّهِ صلى الله عليه و سلم "دَعْ مَا يُرِيبُك إلَى مَا لَا يُرِيبُك". رَوَاهُ التِّرْمِذِيُّ ، وَقَالَ التِّرْمِذِيُّ: حَدِيثٌ حَسَنٌ صَحِيحٌ.', narrator: 'علي بن أبي طالب رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 10, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "مِنْ حُسْنِ إسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ". حَدِيثٌ حَسَنٌ، رَوَاهُ التِّرْمِذِيُّ .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 11, text: 'عَنْ أَبِي حَمْزَةَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ خَادِمِ رَسُولِ اللَّهِ صلى الله عليه و سلم عَنْ النَّبِيِّ صلى الله عليه و سلم قَالَ: "لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ". رَوَاهُ الْبُخَارِيُّ . ،', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 12, text: 'عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ". ،', narrator: 'ابن مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 13, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ، وَمَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ". ،', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 14, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صلى الله عليه و سلم أَوْصِنِي. قَالَ: لَا تَغْضَبْ، فَرَدَّدَ مِرَارًا، قَالَ: لَا تَغْضَبْ" . .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 15, text: 'عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صلى الله عليه و سلم قَالَ: "إنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ". .', narrator: 'شداد بن أوس رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 16, text: 'عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صلى الله عليه و سلم قَالَ: "اتَّقِ اللَّهَ حَيْثُمَا كُنْت، وَأَتْبِعْ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقْ النَّاسَ بِخُلُقٍ حَسَنٍ" . رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ، وَفِي بَعْضِ النُّسَخِ: حَسَنٌ صَحِيحٌ.', narrator: 'أبي ذر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 17, text: 'عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الْأَنْصَارِيِّ الْبَدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "إنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْت" . .', narrator: 'أبي مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 18, text: 'عَنْ أَبِي عَمْرٍو وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: "قُلْت: يَا رَسُولَ اللَّهِ! قُلْ لِي فِي الْإِسْلَامِ قَوْلًا لَا أَسْأَلُ عَنْهُ أَحَدًا غَيْرَك؛ قَالَ: قُلْ: آمَنْت بِاَللَّهِ ثُمَّ اسْتَقِمْ" . .', narrator: 'عمر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 19, text: 'عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا: "أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صلى الله عليه و سلم فَقَالَ: أَرَأَيْت إذَا صَلَّيْت الْمَكْتُوبَاتِ، وَصُمْت رَمَضَانَ، وَأَحْلَلْت الْحَلَالَ، وَحَرَّمْت الْحَرَامَ، وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا؛ أَأَدْخُلُ الْجَنَّةَ؟ قَالَ: نَعَمْ". .', narrator: 'جابر بن عبد الله رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 20, text: 'عَنْ أَبِي مَالِكٍ الْحَارِثِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "الطَّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآنِ -أَوْ: تَمْلَأُ- مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَك أَوْ عَلَيْك، كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا". .', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 21, text: 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ أَيْضًا، "أَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه و سلم قَالُوا لِلنَّبِيِّ صلى الله عليه و سلم يَا رَسُولَ اللَّهِ ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ؛ يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ. قَالَ: أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِمَعْرُوفٍ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إذَا وَضَعَهَا فِي الْحَلَالِ، كَانَ لَهُ أَجْرٌ". .', narrator: 'أبي ذر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 22, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "كُلُّ سُلَامَى مِنْ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ". ، .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 23, text: 'عَنْ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ صلى الله عليه و سلم قَالَ: "الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِك، وَكَرِهْت أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ" رَوَاهُ مُسْلِمٌ . وَعَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْت رَسُولَ اللَّهِ صلى الله عليه و سلم فَقَالَ: "جِئْتَ تَسْأَلُ عَنْ الْبِرِّ؟ قُلْت: نَعَمْ. فقَالَ: استفت قلبك، الْبِرُّ مَا اطْمَأَنَّتْ إلَيْهِ النَّفْسُ، وَاطْمَأَنَّ إلَيْهِ الْقَلْبُ، وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاك النَّاسُ وَأَفْتَوْك" . حَدِيثٌ حَسَنٌ، رَوَيْنَاهُ في مُسْنَدَي الْإِمَامَيْنِ أَحْمَدَ بْنِ حَنْبَلٍ بِإِسْنَادٍ حَسَنٍ.', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 24, text: 'عَنْ أَبِي نَجِيحٍ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: "وَعَظَنَا رَسُولُ اللَّهِ صلى الله عليه و سلم مَوْعِظَةً وَجِلَتْ مِنْهَا الْقُلُوبُ، وَذَرَفَتْ مِنْهَا الْعُيُونُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا، قَالَ: أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ". وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ.', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 25, text: 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُومِ بن نَاشِر رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صلى الله عليه و سلم قَال: "إنَّ اللَّهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا". حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيّ ْ"في سننه" ، وَغَيْرُهُ.', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 26, text: 'عَنْ أَبِي الْعَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إلَى النَّبِيِّ صلى الله عليه و سلم فَقَالَ: يَا رَسُولَ اللهِ! دُلَّنِي عَلَى عَمَلٍ إذَا عَمِلْتُهُ أَحَبَّنِي اللهُ وَأَحَبَّنِي النَّاسُ؛ فَقَالَ: "ازْهَدْ فِي الدُّنْيَا يُحِبَّك اللهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّك النَّاسُ" . حديث حسن، رَوَاهُ ابْنُ مَاجَهْ ، وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ.', narrator: 'سهل بن سعد رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 27, text: 'عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الْخُدْرِيّ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: " لَا ضَرَرَ وَلَا ضِرَارَ" . حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ فِي "الْمُوَطَّإِ" عَنْ عَمْرِو بْنِ يَحْيَى عَنْ أَبِيهِ عَنْ النَّبِيِّ صلى الله عليه و سلم مُرْسَلًا، فَأَسْقَطَ أَبَا سَعِيدٍ، وَلَهُ طُرُقٌ يُقَوِّي بَعْضُهَا بَعْضًا.', narrator: '', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 28, text: 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: "لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى رِجَالٌ أَمْوَالَ قَوْمٍ وَدِمَاءَهُمْ، لَكِنَّ الْبَيِّنَةَ عَلَى الْمُدَّعِي، وَالْيَمِينَ عَلَى مَنْ أَنْكَرَ" . حَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيّ ، وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي "الصَّحِيحَيْنِ".', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 29, text: 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيّ رَضِيَ اللهُ عَنْهُ قَالَ سَمِعْت رَسُولَ اللَّهِ صلى الله عليه و سلم يَقُولُ: "مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ" . .', narrator: 'أبي سعيد الخدري رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 30, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم " لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللَّهِ إخْوَانًا، الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَكْذِبُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا، وَيُشِيرُ إلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ، بِحَسْبِ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ وَمَالُهُ وَعِرْضُهُ" . .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 31, text: 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ صلى الله عليه و سلم قَالَ: "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ، يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِما سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ ، وَاَللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ، وَيَتَدَارَسُونَهُ فِيمَا بَيْنَهُمْ؛ إلَّا نَزَلَتْ عَلَيْهِمْ السَّكِينَةُ، وَغَشِيَتْهُمْ الرَّحْمَةُ، وَ حَفَّتهُمُ المَلاَئِكَة، وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ أَبَطْأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ". بهذا اللفظ.', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 32, text: 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ صلى الله عليه و سلم فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، قَالَ: "إنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ، فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إلَى سَبْعِمِائَةِ ضِعْفٍ إلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً". ، ، في "صحيحيهما" بهذه الحروف.', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 33, text: 'عَنْ أَبِي هُرَيْرَة رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُول اللَّهِ صلى الله عليه و سلم إنَّ اللَّهَ تَعَالَى قَالَ: "مَنْ عَادَى لِي وَلِيًّا فَقْد آذَنْتهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إلَيَّ مِمَّا افْتَرَضْتُهُ عَلَيْهِ، وَلَا يَزَالُ عَبْدِي يَتَقَرَّبُ إلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْت سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَلَئِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ". .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 34, text: 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: "إنَّ اللَّهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ" . حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ .', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 35, text: 'عَنْ ابْن عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ صلى الله عليه و سلم بِمَنْكِبِي، وَقَالَ: "كُنْ فِي الدُّنْيَا كَأَنَّك غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ". وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: إذَا أَمْسَيْتَ فَلَا تَنْتَظِرْ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرْ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِك لِمَرَضِك، وَمِنْ حَيَاتِك لِمَوْتِك. .', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 36, text: 'عَنْ أَبِي مُحَمَّدٍ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم "لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ". حَدِيثٌ حَسَنٌ صَحِيحٌ، رَوَيْنَاهُ فِي كِتَابِ "الْحُجَّةِ" بِإِسْنَادٍ صَحِيحٍ.', narrator: 'عبد الله بن عمرو رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 37, text: 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْت رَسُولَ اللَّهِ صلى الله عليه و سلم يَقُولُ: قَالَ اللَّهُ تَعَالَى: "يَا ابْنَ آدَمَ! إِنَّكَ مَا دَعَوْتنِي وَرَجَوْتنِي غَفَرْتُ لَك عَلَى مَا كَانَ مِنْك وَلَا أُبَالِي، يَا ابْنَ آدَمَ! لَوْ بَلَغَتْ ذُنُوبُك عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتنِي غَفَرْتُ لَك، يَا ابْنَ آدَمَ! إنَّك لَوْ أتَيْتنِي بِقُرَابِ الْأَرْضِ خَطَايَا ثُمَّ لَقِيتنِي لَا تُشْرِكُ بِي شَيْئًا لَأَتَيْتُك بِقُرَابِهَا مَغْفِرَةً" . رَوَاهُ التِّرْمِذِيُّ ، وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ.', narrator: 'أنس بن مالك رضي الله عنه', grade: 'SAHIH', topic: 'الأربعون النووية', source: 'الأربعون النووية' },
  { id: 38, text: 'وعن أبي نجيد- ضم النون وفتح الجيم - عمران بن الحصين الخزاعى رضي الله عنهما أن امرأة من جهينة أتت رسول الله صلى الله عليه وسلم وهى حبلى من الزنى، فقالت: يا رسول الله أصبت حداً فأقمه علي، فدعا نبي الله صلى الله عليه وسلم وليها فقال: أحسن إليها، فإذا وضعت فأتني، ففعل فأمر بها نبي الله صلى الله عليه وسلم، فشدت عليها ثيابها، ثم أمر بها فرجمت، ثم صلى الله عليه وآله وسلم عليها. فقال له عمر: تصلى عليها يا رسول الله وقد زنت، قال: لقد تابت توبة لو قمست بين سبعين من أهل المدينة لوستعتهم، وهل وجدت أفضل من أن جادت بنفسها لله عز وجل ؟! " رواه مسلم.', narrator: 'عمر رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 39, text: 'وعن أبي هريرة رضي الله عنه ، أن رجلاً قال للنبي صلى الله عليه وسلم: أوصني، قال: "لا تغضب" فردد مراراً، قال: " لاتغضب" رواه البخاري.', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 40, text: 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من قال-يعني إذا خرج من بيته-: بسم الله توكلت على الله، ولا حول ولا قوة إلا بالله ، يقال له: هديت وكفيت ووقيت، وتنحى عنه الشيطان". رواه أبو داود والترمذي، والنسائي وغيرهم. وقال الترمذي: حديث حسن، زاد أبو داود: "فيقول :-يعني الشيطان-لشيطان آخر: كيف لك برجل قد هدي وكفي ووقيّ ؟', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 41, text: 'عن جابر رضي الله عنه قال: قال رجل للنبي صلى الله عليه وسلم يوم أحد: : رَأيتَ إنْ قُتِلتُ فَأَيْنَ أَنَا ؟ قَالَ : « في الجنَّةِ » فَأَلْقَى تَمَرَاتٍ كُنَّ في يَدِهِ ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ . مُتَّفَقٌ عَلَيهِ .', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 42, text: 'عن أبي هريرة ، قَالَ : جاءَ رَجُلٌ إِلَى النَّبيِّ فَقَالَ : يَا رسولَ الله ، أيُّ الصَّدَقَةِ أعْظَمُ أجْرَاً ؟ قَالَ : « أنْ تَصَدَّقَ وَأنتَ صَحيحٌ شَحيحٌ ، تَخشَى الفَقرَ وتَأمُلُ الغِنَى ، وَلا تُمهِلْ حَتَّى إِذَا بَلَغتِ الحُلقُومَ قُلْتَ لِفُلان كذا ولِفُلانٍ كَذا ، وقَدْ كَانَ لِفُلانٍ » . مُتَّفَقٌ عَلَيهِ .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 43, text: 'وعن معاوية بن حيدة رضي الله عنه قال : قلت يا رسول الله صلى الله عليه وسلم ما حق زوجة أحدنا عليه؟ قال: "أن تطعمها إذا طعمت ، وتكسوها إذا اكتسيت ولا تضرب الوجه، ولا تقبح، ولا تهجر إلا في البيت " حديث حسن رواه أبو داود وقال: معنى "لاتقبح" أي : لا تقل قبحك الله.', narrator: '', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 44, text: 'و عن أبي ثرية سبرة بن معبد الجهني رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : " علموا الصبي الصلاة لسبع سنين" واضربوه عليها ابن عشر سنين" حديث حسن رواه أبو داود، والترمذي وقال حديث حسن. ولفظ أبي داود: " مروا الصبي بالصلاة إذا بلغ سبع سنين".', narrator: '', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 45, text: 'وعنه أيضاً أن رسول الله قَالَ : « مَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيُكْرِمْ ضَيْفَهُ ، وَمَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيَصِلْ رَحِمَهُ ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَاليَومِ الآخِرِ ، فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ » . مُتَّفَقٌ عَلَيهِ .', narrator: '', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 46, text: 'وعنه عن النبي صلى الله عليه وسلم قال: " رغم أنف، ثم رغم أنف، ثم رغم أنف من أدرك أبويه عند الكبر، أحدهما أو كليهما، فلم يدخل الجنة"', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'صحيح مسلم' },
  { id: 47, text: 'وعنه أن رجلاً قَالَ : يَا رَسُول الله ! إنّ لِي قَرابةً أصِلُهُمْ وَيَقْطَعُوني ، وَأُحْسِنُ إلَيْهِمْ وَيُسِيئُونَ إلَيَّ ، وَأحْلَمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ ، فَقَالَ : " لَئِنْ كُنْتَ كَمَا قُلْتَ ، فَكأنَّمَا تُسِفُّهُمْ الْمَلَّ ، وَلا يَزَالُ مَعَكَ مِنَ اللهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذلِكَ ".', narrator: '', grade: 'SAHIH', topic: 'المقدمات', source: 'صحيح مسلم' },
  { id: 48, text: 'وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النَّبيّ قَالَ : "الكَبَائِرُ : الإشْرَاكُ بالله ، وَعُقُوقُ الوَالِدَيْنِ ، وَقَتْلُ النَّفْس ، وَاليَمِينُ الغَمُوسُ" .', narrator: 'عبد الله بن عمرو رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'صحيح البخاري' },
  { id: 49, text: 'عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال: "إن أبر البر أن يصل الرجل ود أبيه".', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 50, text: 'وعنه قال: قال رسول الله صلى الله عليه وسلم :"أن رجلاً زار أخًا له في قريةٍ أخرى، فأرصد الله له على مدرجته ملكاً" وذكر الحديث إلى قوله: "إن الله قد أحبك كما أحببته فيه" (', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'صحيح مسلم' },
  { id: 51, text: 'وعن جابر قَالَ : جاء أعرابي إِلَى النَّبيّ فَقَالَ : يَا رَسُول الله ، مَا الموجِبَتَانِ ؟ قَالَ : « مَنْ مَاتَ لا يُشْرِكُ بالله شَيئاً دَخَلَ الجَنَّةَ ، وَمَنْ مَاتَ يُشْرِكُ بِهِ شَيْئاً دَخَلَ النَّار » . رواه مسلم .', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'المقدمات', source: 'رياض الصالحين' },
  { id: 52, text: 'عن عمر بن أبى سلمة رضى الله عنهما قال: قال لي رسول الله صلى الله عليه وسلم: "سم الله وكل بيمينك، وكل مما يليك".', narrator: 'عمر رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 53, text: 'وعن عائشة رضى الله عنها قالت : قال رسول الله صلى الله عليه وسلم: "إذا أكل أحدكم فليذكر اسم الله تعالى، فإذا نسى أن يذكر اسم الله تعالى في أوله، فليقل، بسم الله أوله وآخره".', narrator: 'عائشة رضي الله عنها', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود والترمذي' },
  { id: 54, text: 'وعن جابر، رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إذا دخل الرجل بيته، فذكر الله تعالى عند دخوله وعند طعامه، قال الشيطان لأصحابه: لا مبيت لكم ولا عشاء، وإذا دخل ، فلم يذكر الله تعالى عند دخوله، قال الشيطان: أدركتم المبيت؛ وإذا لم يذكر الله تعالى عند طعامه قال: أدركتم المبيت والعشاء" .', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 55, text: 'وعن حذيفة رضى الله عنه قال: كنا إذا حضرنا مع رسول الله صلى الله عليه وسلم طعاماً، لم نضع أيدينا حتى يبدأ رسول الله صلى الله عليه وسلم فيضع يده. وإنا حضرنا معه مرةً طعاماً، فجاءت جارية كأنها تدفع، فذهبت لتضع يدها في الطعام، فأخذ رسول الله صلى الله عليه وسلم بيدها، ثم جاء أعرابي كأنما يدفع فأخذ بيده، فقال رسول الله صلى الله عليه وسلم: "إن الشيطان يستحل الطعام أن لا يذكر اسم الله تعالى عليه، وإنه جاء بهذه الجارية ليستحل بها، فأخذت بيدها، فجاء بهذا الأعرابي ليستحل به، فأخذت بيده، والذي نفسي بيده إن يده في يدي مع يديهما" ثم ذكر اسم الله تعالى وأكل.', narrator: 'حذيفة رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 56, text: 'وعن أمية بن مخشى الصحابي رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم جالساً ، ورجل يأكل، فلم يسم الله حتى لم يبق من طعامه إلا لقمة، فلما رفعها إلى فيه، قال: بسم الله أوله وآخره، فضحك النبي صلى الله عليه وسلم، ثم قال: "ما زال الشيطان يأكل معه، فلما ذكر اسم الله استقاء ما فيه بطنه" .', narrator: '', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود والنسائي' },
  { id: 57, text: 'وعن عائشة رضى الله عنها قالت: كان رسول الله صلى الله عليه وسلم يأكل طعاماً في ستة من أصحابه، فجاء أعرابى، فأكله بلقمتين. فقال رسول الله صلى الله عليه وسلم "أما إنه لو سمى لكفاكم".', narrator: 'عائشة رضي الله عنها', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه الترمذي' },
  { id: 58, text: 'وعن معاذ بن أنس رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: "من أكل طعاماً فقال: الحمد الله الذي أطعمني هذا، ورزقنيه من غير حول منى ولا قوةٍ، غفر له ما تقدم من ذنبه" .', narrator: '', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود والترمذي' },
  { id: 59, text: 'وعن أبى هريرة رضى الله عنه قال: "ما عاب رسول الله صلى الله عليه وسلم طعاماً قط، إن اشتهاه أكله، وإن كرهه تركه" .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 60, text: 'وعن جابر رضى الله عنه أن النبي صلى الله عليه وسلم سأل أهله الأدم فقالوا: ما عندنا إلا خل، فدعا به، فجعل يأكل ويقول: "نعم الأدم الخل، نعم الأدم الخل" .', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 61, text: 'عن أبى هريرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : "إذا دعي أحدكم ، فليجب، فإن كان صائما فليصل، وإن كان مفطراً فليطعم" .', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 62, text: 'عن أبى مسعود البدرى رضى الله عنه قال: دعا رجل النبي صلى الله عليه وسلم لطعام صنعه له خامس خمسة، فتبعهم رجل، فلما بلغ الباب، قال النبي صلى الله عليه وسلم: "إن هذا تبعنا؛ فإن شئت أن تأذن له، وإن شئت رجع" قال: بل آذن له يا رسول الله .', narrator: 'أبي مسعود رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 63, text: 'عن عمر بن أبى سلمة رضى الله عنهما قال: كنت غلاماً في حجر رسول الله صلى الله عليه وسلم، وكانت يدي تطيش في الصحفة، فقال لي رسول الله صلى الله عليه وسلم: " يا غلام سم الله تعالى، وكل بيمينك،وكل مما يليك" .', narrator: 'عمر رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 64, text: 'وعن سلمةَ بن الأَكْوَع أنَّ رَجُلاً أَكَلَ عِنْدَ رَسُولِ الله بِشِمَالِهِ ، فَقَالَ : « كُلْ بِيَمِينِكَ » قَالَ : لا أسْتَطِيعُ . قَالَ : « لا اسْتَطَعْتَ » ! مَا مَنَعَهُ إِلا الكِبْرُ ! فَمَا رَفَعَهَا إِلَى فِيهِ .', narrator: '', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 65, text: 'عن جبلة بن سحيم قال: أصابنا عام سنةٍ مع ابن الزبير، فرزقنا تمراً، وكان عبد الله بن عمر رضى الله عنهما يمر بنا ونحن نأكل، فيقول: لا تقارونوا، فإن النبى نهى عن الإقران، ثم يقول: "إلا أن يستأذن الرجل أخاه"', narrator: '', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 66, text: 'عن وحشى بن حرب رضى الله عنه أن أصحاب رسول الله صلى الله عليه وسلم قالوا: يا رسول الله ، إنا نأكل ولا نشبع قال: "فلعلكم تفترقون" قالوا: نعم. قال: فاجتمعوا على طعامكم، واذكروا اسم الله ، يبارك لكم فيه"', narrator: '', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود' },
  { id: 67, text: 'وعن ابن عباس رضى الله عنهما عن النبي صلى الله عليه وسلم قال: "البركة تنزل وسط الطعام، فكلوا من حافتيه ولا تأكلوا من وسطه".', narrator: 'ابن عباس رضي الله عنه', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود والترمذي' },
  { id: 68, text: 'وعن عبد الله بن بشر رضى الله عنه قال: كان للنبي صلى الله عليه وسلم قصعة يقال لها: الغراء، يحملها أربعة رجال، فلما أضحوا وسجدوا الضحى أتى بتلك القصعة، يعنى وقد ثرد فيها، فالتقوا عليه ، فلما كثروا جثا رسول الله صلى الله عليه وسلم.فقال أعرابي : ما هذه الجلسة؟ قال رسول الله صلى الله عليه وسلم : إن الله جعلني عبداً كريماً، ولم يجعلني جباراً عنيداً، ثم قال رسول الله صلى الله عليه وسلم : "كلوا من حواليها، ودعوا ذروتها يبارك فيها" .', narrator: '', grade: 'HASAN', topic: 'أدب الطعام', source: 'رواه أبو داود' },
  { id: 69, text: 'وعن أنس رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم جالساً مقعياً يأكل تمراً.', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 70, text: 'عن ابن عباس رضى الله عنهما قال: قال رسول الله صلى الله عليه وسلم: "إذا أكل أحدكم طعاماً، فلا يمسح أصابعه حتى يلعقها أو يلعقها".', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 71, text: 'وعن جابر رضى الله عنه أن رسول الله صلى الله عليه وسلم أمر بلعق الأصابع والصحفة، وقال: "إنكم لا تدرون في أي طعامكم البركة".', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'أدب الطعام', source: 'صحيح مسلم' },
  { id: 72, text: 'وعن ابن عباس رضى الله عنهما أن رسول الله صلى الله عليه وسلم قال: إلبسوا من ثيابكم البياض؛ فإنها من خير ثيابكم، وكفنوا فيها موتاكم".', narrator: 'ابن عباس رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 73, text: 'وعن سمرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : "إلبسوا البياض؛ فإنها أطهر وأطيب، وكفنوا فيها موتاكم".', narrator: '', grade: 'HASAN', topic: 'اللباس', source: 'رواه النسائي والحاكم' },
  { id: 74, text: 'وعن البراء رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم مربوعاً، ولقد رأيته في حلةٍ حمراء ما رأيت شيئاً قط أحسن منه.', narrator: '', grade: 'SAHIH', topic: 'اللباس', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 75, text: 'وعن أبى جحيفة وهب بن عبد الله رضى الله عنه قال: رأيت النبي صلى الله عليه وسلم بمكة وهو بالأبطح في قبة له حمراء من آدم، فخرج بلال بوضوئه، فمن ناضح ونائل، فخرج النبي صلى الله عليه وسلم وعليه حلة حمراء، كأني أنظر إلى بياض ساقيه، فتوضأ وأذن بلال، فجعلت أتتبع فاه ههنا وههنا، يقول يمينا وشمالاً: حي على الصلاة، حي على الفلاح، ثم ركزت له عنزة، فتقدم فصلى يمر بين يديه الكلب والحمار لا يمنع.', narrator: 'أبي جحيفة رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 76, text: 'وعن أبى رمثة رفاعة التيمى رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم وعليه ثوبان أخضران.', narrator: '', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 77, text: 'وعن جابر رضى الله عنه ، أن رسول الله صلى الله عليه وسلم دخل يوم فتح مكة وعليه عمامة سوداء.', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'صحيح مسلم' },
  { id: 78, text: 'وعنها قالت: خرج رسول الله صلى الله عليه وسلم ذات غداة، وعليه مرط مرحل من شعر أسود.', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'صحيح مسلم' },
  { id: 79, text: 'عن أم سلمة رضى الله عنها قالت: كان أحب الثياب إلى رسول الله صلى الله عليه وسلم القميص.', narrator: 'أم سلمة رضي الله عنها', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 80, text: 'عن أسماء بنت يزيد الأنصارية رضى الله عنها قالت: كان كم قميص رسول الله صلى الله عليه وسلم إلى الرسغ.', narrator: '', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 81, text: 'وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: "لا ينظر الله يوم القيامة إلى من جر إزاره بطراً".', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 82, text: 'وعن أبى ذر رضى الله عنه عن النبي صلى الله عليه وسلم قال: "ثلاثة لا يكلمهم الله يوم القيامة، ولا ينظر إليهم ، ولا يزكيهم، ولهم عذاب أليم" قال: فقرأها رسول الله صلى الله عليه وسلم ثلاث مرار. قال أبو ذر : خابوا وخسروا ‍ من هم يا رسول الله ؟ قال: "المسبل، والمنان، والمنفق سلعته بالحلف الكاذب". وفى رواية له: "المسبل إزاره".', narrator: 'أبي ذر رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'صحيح مسلم' },
  { id: 83, text: 'وعن ابن عمر رضى الله عنهما ، عن النبي صلى الله عليه وسلم قال: "الإسبال من الإزار، والقميص، والعمامة؛ من جر شيئاً خيلاء لم ينظر الله إليه يوم القيامة".', narrator: 'ابن عمر رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والنسائي' },
  { id: 84, text: 'وعن أبى جرى جابر بن سليم رضى الله عنه قال: رأيت رجلا يصدر الناس عن رأيه ؛ لا يقول شيئاً إلا صدروا عنه؛ قلت: من هذا قالوا: رسول الله صلى الله عليه وسلم.قلت: عليك السلام يا رسول الله - مرتين- قال: "لا تقل عليك السلام، عليك السلام تحية الموتى -قلت : السلام عليك" قال: قلت: أنت رسول الله ؟ قال: "أنا رسول الله إذا أصابك ضر فدعوته كشفه عنك،وإذا أصابك عام سنة فدعوته أنبتها لك، وإذا كنت بأرض قفر أو فلاة، فضلت راحلتك، فدعوته ردها عليك" قال: قلت: اعهد إلى. قال: "لا تسبن أحداً" قال: فما سببت بعده حراً، ولا عبداً، ولا بعيراً، ولا شاة "ولا تحقرن من المعروف شيئاً، وأن تكلم أخاك وأنت منبسط إليه وجهك؛ إن ذلك من المعروف. وارفع إزارك إلى نصف الساق، فإن أبيت فإلى الكعبين، وإياك وإسبال الإزار فإنها من المخيلة وإن الله لا يحب المخيلة، وإن امرؤا شتمك وعيرك، بما يعلم فيك فلا تعيره بما تعلم فيه، فإنما وبال ذلك عليه".', narrator: 'جابر رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 85, text: 'وعن أبى هريرة رضى الله عنه قال: بينما رجل يصلى مسبل إزاره، قال له رسول الله صلى الله عليه وسلم: "اذهب فتوضأ" فذهب فتوضأ، ثم جاء فقال :" اذهب فتوضأ" فقال رجل يا رسول الله ما لك أمرته أن يتوضأ ثم سكت عنه؟ قال: "إنه كان يصلى وهو مسبل إزاره، وإن الله لا يقبل صلاة رجل مسبل".', narrator: 'أبي هريرة رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود' },
  { id: 86, text: 'وعن أبى سعيد الخدرى رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إزارة المسلم إلى نصف الساق، ولا حرج -أو لا جناح- فيما بينه وبين الكعبين، فما كان أسفل من الكعبين فهو في النار، ومن جر إزاره بطرا لم ينظر الله إليه".', narrator: 'أبي سعيد الخدري رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود' },
  { id: 87, text: 'وعن ابن عمر رضى الله عنهما قال: مررت على رسول الله صلى الله عليه وسلم وفى إزاري استرخاء، فقال: "يا عبد الله، ارفع إزارك" فرفعت ثم قال: "زد"، فزدت، فما زلت أتحراها بعد. فقال بعض القوم: إلى أين ؟ فقال: إلى أنصاف الساقين".', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'صحيح مسلم' },
  { id: 88, text: 'وعنه قال: قال رسول الله صلى الله عليه وسلم: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة" فقالت أم سلمة: فكيف تصنع النساء بذيولهن، قال: "يرخين شبراً" قالت: ِإذاً تنكشف أقدامهن. قال: "فيرخينه ذراعاً لا يزدن".', narrator: 'علي رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه أبو داود والترمذي' },
  { id: 89, text: 'وعن معاذ بن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: " من ترك اللباس تواضعاً لله، وهو يقدر عليه، دعاه الله يوم القيامة على رؤوس الخلائق حتى يخيره من أي حلل الإيمان شاء يلبسها".', narrator: '', grade: 'HASAN', topic: 'اللباس', source: 'رواه الترمذي' },
  { id: 90, text: 'عن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إن الله يحب أن يرى أثر نعمته على عبده".', narrator: 'عمر رضي الله عنه', grade: 'HASAN', topic: 'اللباس', source: 'رواه الترمذي' },
  { id: 91, text: 'عن عمر بن الخطاب رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : " لا تلبسوا الحرير؛ فإن من لبسه في الدنيا لم يلبسه في الآخرة" .', narrator: 'عمر بن الخطاب رضي الله عنه', grade: 'SAHIH', topic: 'اللباس', source: 'متفق عليه (البخاري ومسلم)' },
  { id: 92, text: 'وعن جابر بن سمرة رضى الله عنه قال: كان النبي صلى الله عليه وسلم إذا صلى الفجر تربع في مجلسه حتى تطلع الشمس حسناء. حديث صحيح، رواه أبو داود وغيره بأسانيد صحيحة.', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 93, text: 'وعن الشريد بن سويد رضى الله عنه قال: مر بي رسول الله صلى الله عليه وسلم وأنا جالس هكذا، وقد وضعت يدي اليسرى خلف ظهري، واتكأت على إلية يدي فقال: "أتقعد قعدة المغضوب عليهم؟!"', narrator: '', grade: 'HASAN', topic: 'آداب النوم', source: 'رواه أبو داود بإسناد صحيح' },
  { id: 94, text: 'وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: "إذا قام أحدكم من مجلس، ثم رجع إليه، فهو أحق به".', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'صحيح مسلم' },
  { id: 95, text: 'وعن جابر بن سمرة رضى الله عنهما قال: كنا إذا أتينا النبي صلى الله عليه وسلم جلس أحدنا حيث ينتهي.', narrator: 'جابر رضي الله عنه', grade: 'HASAN', topic: 'آداب النوم', source: 'رواه أبو داود والترمذي' },
  { id: 96, text: 'وعن أبى عبد الله سلمان الفارسي رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: "لا يغتسل رجل يوم الجمعة، ويتطهر ما استطاع من طهر، ويدهن من دهنه، أو يمس من طيب بيته، ثم يخرج فلا يفرق بين اثنين، ثم يصلى ما كتب له، ثم ينصت إذا تكلم الإمام، إلا غفر له ما بينه وبين الجمعة الأخرى"', narrator: '', grade: 'SAHIH', topic: 'آداب النوم', source: 'صحيح البخاري' },
  { id: 97, text: 'وعن عمرو بن شعيب عن أبيه عن جده رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: "لا يحل لرجل أن يفرق بين اثنين إلا بإذنهما" رواه أبو داود والترمذي وقال "حديث حسن". وفى رواية لأبى داود: "لا يجلس بين رجلين إلا بإذنهما".', narrator: 'عمر رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 98, text: 'وعن حذيفة بن اليمان رضى الله عنه أن رسول الله صلى الله عليه وسلم لعن من جلس وسط الحلقة. رواه أبو داود بإسناد صحيح. وروى الترمذى عن أبى مجلز: أن رجلا قعد وسط الحلقة، فقال حذيفة: ملعون على لسان محمد صلى الله عليه وسلم -من جلس وسط الحلقة. قال الترمذى: "حديث حسن صحيح".', narrator: 'حذيفة رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 99, text: 'وعن أبى سعيد الخدرى رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "خير المجالس أوسعها".', narrator: 'أبي سعيد الخدري رضي الله عنه', grade: 'HASAN', topic: 'آداب النوم', source: 'رواه أبو داود بإسناد صحيح على شرط البخاري' },
  { id: 100, text: 'وعن أبى هريرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم "من جلس في مجلس، فكثر فيه لغطه فقال قبل أن يقوم من مجلسه ذلك: سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك، إلا غفر له ما كان في مجلسه ذلك"', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 101, text: 'وعن ابن عمر رَضِيَ اللَّهُ عَنهُ قال: قلما كان رَسُول اللَّهِ ﷺ يقوم من مجلس حتى يدعو بهؤلاء الدعوات: "اللهم اقسم لنا من خشيتك ما تحول به بيننا وبين معاصيك، ومن طاعتك ما تبلغنا به جنتك، ومن اليقين ما تهون به علينا مصائب الدنيا، اللهم متعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همنا، ولا مبلغ علمنا، ولا تسلط علينا من لا يرحمنا"', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 102, text: 'وعن أبي هريرة رَضِيَ اللَّهُ عَنهُ قال، قال رَسُول اللَّهِ ﷺ: "ما من قوم يقومون من مجلس ولا يذكرون اللَّه تعالى فيه إلا قاموا عن مثل جيفة حمار وكان لهم حسرة"', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 103, text: 'وعنه قال: قال رسول الله صلى الله عليه وسلم: "من رآني في المنام فسيراني في اليقظة -أو كأنما رآني في اليقظة- لا يتمثل الشيطان بي"', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 104, text: 'وعن أبى سعيد الخدرى رضى الله عنه انه سمع النبي صلى الله عليه وسلم، يقول: "إذا رأى أحدكم رؤيا يحبها، فإنما هي من الله تعالى، فليحمد الله عليها، وليحدث بها -وفى رواية، فلا يحدث بها إلا من يحب- وإذا رأى غير ذلك مما يكره، فإنما هي من الشيطان، فليستعذ من شرها، ولا يذكرها لأحد، فإنها لا تضره"', narrator: 'أبي سعيد الخدري رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 105, text: 'وعن جابر رضى الله عنه عن رسول الله صلى الله عليه وسلم قال: "إذا رأى أحدكم الرؤيا يكرهها، فليبصق عن يساره ثلاثاً، وليستعذ بالله من الشيطان ثلاثاً، وليتحول عن جنبه الذي كان عليه"', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 106, text: 'وعن أبى الأسقع واثلة بن الأسقع رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إن من أعظم الفرى أن يدعى الرجل إلى غير أبيه، أو يرى عينيه ما لم تر، أو يقول على رسول الله صلى الله عليه وسلم ما لم يقل"', narrator: 'واثلة بن الأسقع رضي الله عنه', grade: 'SAHIH', topic: 'آداب النوم', source: 'رياض الصالحين' },
  { id: 107, text: 'عن عائشة رضي الله عنها، قالت: قال رسول الله صلى الله عليه وسلم: “ما من ميت يصلي عليه أمة من المسلمين يبلغون مائة كلهم يشفعون له إلا شفعوا فيه“', narrator: 'عائشة رضي الله عنها', grade: 'SAHIH', topic: 'عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه', source: 'صحيح مسلم' },
  { id: 108, text: 'وعن ابن عباس رَضِيَ اللَّهُ عَنهُما قال سمعت رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيهِ وَسَلَّم يقول : "ما من رجل مسلم يموت فيقوم على جنازته أربعون رجلاً لا يشركون بالله شيئاً إلا شفعهم اللَّه فيه."', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه', source: 'رياض الصالحين' },
  { id: 109, text: 'وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: "إنما مثل صاحب القرآن كمثل الإبل المعقلة، إن عاهد عليها أمسكها، وإن أطلقها، ذهبت" متفق عليه.', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'الفضائل', source: 'رياض الصالحين' },
  { id: 110, text: 'وعن أنس قال : قَالَ رسول الله : « الدُّعَاءُ لا يُرَدُّ بَيْنَ الأَذَانِ وَالإقَامَةِ » . رواه أَبُو داود والترمذي ، وقال :', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'الفضائل', source: 'رياض الصالحين' },
  { id: 111, text: 'عن علي بن أبي طالب، رضي الله عنه قال كان النبي صلى الله عليه وسلم يصلي قلب العصر أربع ركعات يفصل بينهن بالتسليم على الملائكة المقربين ومن تبعهم من المسلمين والمؤمنين. رواه الترمذي وقال حديث حسن.', narrator: 'علي بن أبي طالب رضي الله عنه', grade: 'SAHIH', topic: 'الفضائل', source: 'رياض الصالحين' },
  { id: 112, text: 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابه أحد أو قاتله، فليقل: إني صائم"', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الفضائل', source: 'رياض الصالحين' },
  { id: 113, text: 'وعن أبي ذر رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: "إذا صمت من الشهر ثلاثًا، فصم ثلاث عشرة، وأربع عشرة وخمس عشرة" رواه الترمذي وقال: حديث حسن.', narrator: 'أبي ذر رضي الله عنه', grade: 'SAHIH', topic: 'الفضائل', source: 'رياض الصالحين' },
  { id: 114, text: 'وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال: "ما أحد يدخل الجنة يحب أن يرجع إلى الدنيا وله ما على الأرض من شيء إلا الشهيد، يتمنى أن يرجع إلى الدنيا فيقتل عشر مرات لما يرى من الكرامة”', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'الجهاد', source: 'رياض الصالحين' },
  { id: 115, text: 'وعن سمرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : “رأيت الليلة رجلين أتياني فصعدا بي الشجرة وأدخلاني دارًا هي أحسن وأفضل، لم أر قط أحسن منها، قال أما هذه الدار فدار الشهداء" (5)', narrator: '', grade: 'SAHIH', topic: 'الجهاد', source: 'رياض الصالحين' },
  { id: 116, text: 'وعن جابر رضي الله عنه قال: كنا مع النبي صلى الله عليه وسلم في غزاة فقال: "إن بالمدينة لرجالا ما سرتم مسيرًا، ولا قطعتم واديًا إلا كانوا معكم حبسهم المرض"', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'الجهاد', source: 'رياض الصالحين' },
  { id: 117, text: 'وعن السائب بن يزيد، رضي الله عنه قال: لما قدم النبي صلى الله عليه وسلم من غزوة تبوك تلقاه الناس، فلقيته مع الصبيان على ثنية الوداع. (رواه أبو داود بإسناد صحيح بهذا اللفظ) ورواه البخاري', narrator: '', grade: 'SAHIH', topic: 'الجهاد', source: 'رياض الصالحين' },
  { id: 118, text: 'وعن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من خرج في طلب العلم، فهو في سبيل الله حتى يرجع" رواه الترمذي وقال: حديث حسن.', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'العلم', source: 'رياض الصالحين' },
  { id: 119, text: 'وعن أبي موسى الأشعري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "إذا مات ولد العبد قال الله تعالى لملائكته: قبضتم ولد عبدي؟ فَيقولون : نَعَمْ ، فيقول : قَبَضْتُمْ ثَمَرَةَ فُؤادِهِ ؟ فيقولون : نَعَمْ ، فيقول : فماذا قال عبدي؟ فيقولون: حمدك واسترجع، فيقول الله تعالى: ابنوا لعبدي بيتًا في الجنة، وسموه بيت الحمد". رواه الترمذي وقال حديث حسن.', narrator: 'أبي موسى الأشعري رضي الله عنه', grade: 'SAHIH', topic: 'حمد الله تعالى وشكره', source: 'رياض الصالحين' },
  { id: 120, text: 'وعن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: “أولى الناس بي يوم القيامة أكثرهم علي صلاة" رواه الترمذي وقال حديث حسن.', narrator: 'ابن مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الصلاة على رسول الله صلى الله عليه وسلم', source: 'رياض الصالحين' },
  { id: 121, text: 'وعن أوس بن أوس، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إن من أفضل أيامكم يوم الجمعة، فأكثروا على من الصلاة فيه، فإن صلاتكم معروضة علي" فقالوا: يا رسول الله، كيف تعرض صلاتنا عليك وقد أرمت؟ قال: يقول: بلىت، قال: "إن الله عز وجل حرم على الأرض أجساد الأنبياء" رواه أبو داود بإسناد صحيح.', narrator: '', grade: 'SAHIH', topic: 'الصلاة على رسول الله صلى الله عليه وسلم', source: 'رياض الصالحين' },
  { id: 122, text: 'وعن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "رغم أنف رجل ذكرت عنده فلم يصلِ علي" رواه الترمذي وقال حديث حسن.', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الصلاة على رسول الله صلى الله عليه وسلم', source: 'رياض الصالحين' },
  { id: 123, text: 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "لا تجعلوا قبري عيدًا وصلوا علي، فإن صلاتكم تبلغني حيث كنتم" رواه أبو داود بإسناد صحيح.', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'الصلاة على رسول الله صلى الله عليه وسلم', source: 'رياض الصالحين' },
  { id: 124, text: 'وعن فضالة بن عبيد رضي الله عنه قال: سمع رسول الله صلى الله عليه وسلم رجلا يدعو في صلاته لم يمجد الله تعالى، ولم يصلِ على النبي صلى الله عليه وسلم، فقال رسول الله صلى الله عليه وسلم "عجل هذا" ثم دعاه فقال له -أو لغيره: إذا صلى أحدكم فليبدأ بتحميد ربه سبحانه، والثناء عليه، ثم يصلي على النبي صلى الله عليه وسلم ثم يدعو بعد ما شاء" رواه أبو داود والترمذي وقال حديث صحيح.', narrator: 'فضالة بن عبيد رضي الله عنه', grade: 'SAHIH', topic: 'الصلاة على رسول الله صلى الله عليه وسلم', source: 'رياض الصالحين' },
  { id: 125, text: 'وعن معاذ رضي الله عنه أن رسول الله صلى الله عليه وسلم أخذ بيده وقال: "يا معاذ والله إني لأحبك" فقال: "أوصيك يا معاذ لا تدعن في دبر كل صلاة تقول: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك". رواه أبو داود بإسناد صحيح.', narrator: '', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 126, text: 'وعن جابر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "أفضل الذكر: لا إله إلا الله". رواه الترمذي وقال حديث حسن.', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 127, text: 'وعن عبد الله بن بشر رضي الله عنه أن رجلا قال: يا رسول الله، إن شرائع الإسلام قد كثرت علي، فأخبرني بشيء أتشبث به قال: "لا يزال لسانك رطبًا من ذكر الله". رواه الترمذي وقال حديث حسن.', narrator: '', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 128, text: 'وعن جابر رضي الله عنه، عن النبي صلى الله عليه وسلم قال: "من قال: سبحان الله وبحمده، غرست له نخلة في الجنة". رواه الترمذي وقال حديث حسن.', narrator: 'جابر رضي الله عنه', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 129, text: 'وعن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "لقيت إبراهيم صلى الله عليه وسلم ليلة أسري بي، فقال: يا محمد أقرئ أمتك مني السلام، وأخبرهم أن الجنة طيبة التربة، عذبة الماء، وأنها قيعان، وأن غراسها: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر". رواه الترمذي وقال حديث حسن.', narrator: 'ابن مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 130, text: 'وعن أبي الدرداء، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "ألا أنبئكم بخير أعمالكم، وأزكاها عند مليككم، وأرفعها في درجاتكم، وخير لكم من إنفاق الذهب والفضة وخير لكم من أن تلقوا عدوكم فتضربوا أعناقهم، ويضربوا أعناقكم؟" قالوا: بلى، قال: "ذكر الله تعالى". رواه الترمذي وقال الحاكم أبو عبد الله إسناده صحيح.', narrator: 'أبي الدرداء رضي الله عنه', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 131, text: 'وعن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم يذكر الله تعالى على كل أحيانه. رواه مسلم.', narrator: 'عائشة رضي الله عنها', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 132, text: 'وعنه عنه النبي، صلى الله عليه وسلم، أنه كان يقول إذا أصبح: "اللهم بك أصبحنا، وبك أمسينا، وبك نحيا، وبك نموت، وإليك النشور". وإذا أمسى قال: "اللهم بك أمسينا، وبك نحيا، وبك نموت، وإليك المصير". رواه أبو داود والترمذي وقال حديث حسن.', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 133, text: 'وعنه أن أبا بكر الصديق رضي الله عنه قال: يا رسول الله مرني بكلمات أقولهن إذا أصبحت وإذا أمسيت، قال: قل: "اللهم فاطر السماوات والأرض عالم الغيب والشهادة، رب كل شيء ومليكه أشهد أن لا إله إلا أنت، أعوذ بك من شر نفسي وشر الشيطان وشركه" قال: "قلها إذا أصبحت، وإذا أمسيت، وإذا أخذت مضجعك". رواه أبو داود والترمذي وقال حديث حسن صحيح.', narrator: '', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 134, text: 'وعن عبد الله بن خُبيب -بضم الخاء المعجمة- رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم: "اقرأ: قل هو الله أحد، والمعوذتين حين تمسي وحين تصبح، ثلاث مرات، تكفيك من كل شيء". رواه أبو داود والترمذي وقال حديث حسن صحيح .', narrator: '', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 135, text: 'وعن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "ما من عبد يقول في صباح كل يوم ومساء كل ليلة: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات، إلا لم يضره شيء". رواه أبو داود والترمذي وقال حديث حسن صحيح .', narrator: '', grade: 'SAHIH', topic: 'الأذكار', source: 'رياض الصالحين' },
  { id: 136, text: 'وعن النعمان بن بشير رضي الله عنهما عن النبي صلى الله عليه وسلم قال: "الدعاء هو العبادة".', narrator: '', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 137, text: 'وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم، كان يدعو بهؤلاء الكلمات: "اللهم إني أعوذ بك من فتنة النار، وعذاب النار، ومن شر الغنى والفقر". رواه أبو داود والترمذي وقال حديث حسن صحيح وهذا لفظ أبي داود.', narrator: 'عائشة رضي الله عنها', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 138, text: 'وعن زياد بن علاقة عن عمه، وهو قطبة بن مالك، رضي الله عنه، قال: كان النبي صلى الله عليه وسلم، يقول: "اللهم إني أعوذ بك من منكرات الأخلاق، والأعمال، والأهواء". رواه الترمذي وقال حديث حسن.', narrator: '', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 139, text: 'وعن شكل بن حميد، رضي الله عنه قال: قلت يا رسول الله: علمني دعاء. قال: "قل: اللهم إني أعوذ بك من شر سمعي، ومن شر بصري، ومن شر لساني، ومن شر قلبي، ومن شر مني". رواه أبو داود والترمذي وقال حديث حسن.', narrator: '', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 140, text: 'وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، كان يقول: "اللهم إني أعوذ بك من البرص والجنون، والجذام، وسيئ الأسقام". رواه أبو داود بإسناد صحيح.', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 141, text: 'وعن أبي الدرداء، رضي الله عنه، قال: رسول الله صلى الله عليه وسلم: "كان من دعاء داود عليه السلام: "اللهم إني أسألك حبك، وحب من يحبك، والعمل الذي يبلغني حبك، اللهم اجعل حبك أحب إلى من نفسي، وأهلي، ومن الماء البارد". رواه الترمذي وقال حديث حسن.', narrator: 'أبي الدرداء رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 142, text: 'وعن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "ألظوا بيا ذا الجلال والإكرام". رواه الترمذي ورواه النسائي من رواية ربيعة بن عامر الصحابي قال الحاكم حديث صحيح الإسناد.', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 143, text: 'وعن أبي أمامة، رضي الله عنه قال: دعا رسول الله صلى الله عليه وسلم، بدعاء كثير لم نحفظ منه شيئًا، قلنا: "يا رسول الله دعوت بدعاء كثير لم نحفظ منه شيئا،" فقال: "ألا أدلكم على ما يجمع ذلك كله؟ تقول: "اللهم إني أسألك من خير ما سألك منه نبيك محمد صلى الله عليه وسلم، وأعوذ بك من شر ما استعاذ منه نبيك محمد صلى الله عليه وسلم، وأنت المستعان، وعليك البلاغ، ولا حول ولا قوة إلا بالله". رواه الترمذي وقال حديث حسن.', narrator: 'أبي أمامة رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 144, text: 'وعن أسامة بن زيد رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: "من صنع إليه معروف، فقال لفاعله: جزاك الله خيرًا، فقد أبلغ في الثناء". رواه الترمذي وقال حديث حسن صحيح .', narrator: 'أسامة بن زيد رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 145, text: 'وعن أبي أمامة رضي الله عنه قال: قيل لرسول الله صلى الله عليه وسلم: أي الدعاء أسمع؟ قال: "جوف الليل الآخر ودبر الصلوات المكتوبات". رواه الترمذي وقال حديث حسن.', narrator: 'أبي أمامة رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 146, text: 'وعن عبادة بن الصامت رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "ما على الأرض مسلم يدعو الله تعالى بدعوة إلا آتاه الله إياها، أو صرف عنه من السوء مثلها. ما لم يدع بإثم، أو قطيعة رحم" فقال رجل من القوم: إذًا نكثر قال: "الله أكثر". رواه الترمذي وقال حديث حسن صحيح.', narrator: 'عبادة بن الصامت رضي الله عنه', grade: 'SAHIH', topic: 'الدعوات', source: 'رياض الصالحين' },
  { id: 147, text: 'وعن أبي عبد الرحمن بلال بن الحارث المزني رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "إن الرجل ليتكلم بالكلمة من رضوان الله تعالى ما كان يظن أن تبلغ ما بلغت يكتب الله له بها رضوانه إلى يوم يلقاه، وإن الرجل ليتكلم بالكلمة من سخط الله ما كان يظن أن تبلغ ما بلغت يكتب الله له بها سخطه إلى يوم يلقاه”. رواه مالك في الموطأ والترمذي وقال حديث حسن صحيح.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 148, text: 'وعن سفيان بن عبد الله رضي الله عنه قال: قلت يا رسول الله حدثني بأمر أعتصم به قال: " قل ربي الله ثم استقم" قلت: يا رسول الله ما أخوف ما تخاف علي؟ فأخذ بلسان نفسه، ثم قال: “هذا”. رواه الترمذي وقال حديث حسن صحيح.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 149, text: 'وعن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: "لا تكثروا الكلام بغير ذكر الله، فإن كثرة الكلام بغير ذكر الله تعالى قسوة للقلب! وإن أبعد الناس من الله القلب القاسي". رواه الترمذي.', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 150, text: 'وعن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم ، قال: " من تحلم بحلم لم يره، كُلف أن يعقد بين شعيرتين ولن يفعل، ومن استمع إلى حديث قوم وهم له كارهون، صب في أذنيه الآنُك يوم القيامة، ومن صور صورة، عذب وكلف أن ينفخ فيها الروح وليس بنافخ".رواه البخاري .', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 151, text: 'وعن أبي بكر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "ألا أنبئكم بأكبر الكبائر؟" قلنا: بلى يا رسول الله. قال: "الإشراك بالله، وعقوق الوالدين" وكان متكئا فجلس، فقال: "ألا وقول الزور!" فما زال يكررها حتى قلنا: ليته سكت. متفق عليه', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 152, text: 'وعن أبي الدرداء رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "إن العبد إذا لعن شيئًا، صعدت اللعنة إلى السماء، فتغلق أبواب السماء دونها، ثم تهبط إلى الأرض، فتغلق أبوابها دونها، ثم تأخذ يمينًا وشمالا، فإذا لم تجد مساغًا رجعت إلى الذي لُعن، فإن كان أهلا لذلك، وإلا رجعت إلى قائلها". رواه أبو داود.', narrator: 'أبي الدرداء رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 153, text: 'وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: "إياكم والحسد، فإن الحسد يأكل الحسنات كما تأكل النار الحطب، أو قال: العشب". رواه أَبُو دَاوُدَ', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 154, text: 'وعن معاوية رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إنك إن اتبعت عورات المسلمين أفسدتهم، أو كدت تفسدهم". حديث صحيح رواه أبو داود بإسناد صحيح.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 155, text: 'وعن ابن مسعود رضي الله عنه أنه أتي برجل فقيل له، هذا فلان تقطر لحيته خمرًا، فقال: إنَّا قد نهينا عن التجسس، ولكن إن يظهر لنا شئ، نأخذ به". حديث حسن صحيح رواه أبو داود بإسناد على شرط البخاري ومسلم.', narrator: 'ابن مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 156, text: 'وعن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من خبب زوجة امرئ، أو مملوكه، فليس منا". "خَبَب" بخاء معجمة، ثم باء موحدة مكررة: أي: أفسده وخدعه.', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 157, text: 'وعن ابن مسعود رضي الله عنه قال: كنا مع رسول الله صلى الله عليه وسلم في سفر، فانطلق لحاجته، فرأينا حمرة معها فرخان، فأخذنا فرخيها، فجاءت الحمرة فجعلت تعرش فجاء النبي صلى الله عليه وسلم فقال: "من فجع هذه بولدها؟ ردوا ولدها إليها" ورأى قرية نمل قد حرقناها، فقال: "من حرق هذه؟" قلنا: نحن. قال: "إنه لا ينبغي أن يعذِّب بالنار إلا رب النار". قوله: قرية نمل معناه: موضع النمل مع النمل.', narrator: 'ابن مسعود رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 158, text: 'وعن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم " من تعلم علمًا مما يبتغى به وجه الله عز وجل لا يتعلمه إلا ليصيب به عرضًا من الدنيا، لم يجد عَرف الجنة يوم القيامة" يعني ريحها. رواه أبو داود بإسناد صحيح والأحاديث في الباب كثير مشهورة.', narrator: 'أبي هريرة رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 159, text: 'وعنه قال: رأى رسول الله صلى الله عليه وسلم صبيًا قد حلق بعض شعر رأسه وترك بعضه فنهاهم عن ذلك وقال: "احلقوه كله، أو اتركوه كله". رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم.', narrator: 'علي رضي الله عنه', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 160, text: 'وعن عبد الله بن جعفر رضي الله عنهما أن النبي صلى الله عليه وسلم أمهل آل جعفر رضي الله عنه ثلاثًا، ثم أتاهم فقال: "لا تبكوا على أخي بعد اليوم". ثم قال: "ادعوا لي بني أخي" فجيء بنا كأننا أفرخ فقال: "ادعوا لي الحلاق" فأمره، فحلق رءوسنا". رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 161, text: 'وعَنْ أسْمَاءَ رَضِيَ اللَّه عنْهَا: أنَّ امْرأَةً سألتِ النبيَّ ﷺ فَقَالتْ: يا رَسُولَ اللَّه، إنَّ ابْنَتِي أصَابَتْهَا الْحَصْبةُ، فتَمَرَّقَ شَعْرُهَا، وإنِّي زَوَّجْتُها، أفَأَصِلُ فِيهِ؟ فقالَ: لَعَنَ اللَّه الْواصِلةَ والْمَوصولة متفقٌ عليه.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 162, text: 'وعَنْ عائشة رضي اللَّه عنْهَا نَحْوُهُ، متفقٌ عليه.', narrator: 'عائشة رضي الله عنها', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 163, text: 'وَعَنْ حميْدِ بن عبْدِ الرَّحْمن أنَّهُ سَمِعَ مُعاويَةَ رضي اللَّه عنْهُ عامَ حجَّ علَى المِنْبَر وَتَنَاول قُصَّةً مِنْ شَعْرٍ كَانَتْ في يَدِ حَرِسيٍّ فَقَالَ: يَا أهْل المَدِينَةِ أيْنَ عُلَمَاؤكُمْ؟، سمِعْتُ النبيَّ صَلّى اللهُ عَلَيْهِ وسَلَّم يَنْهَى عنْ مِثْلِ هَذِهِ ويقُولُ: "إنًَّمَا هَلَكَتْ بنُو إسْرَائِيل حِينَ اتخذ هذه نِسَاؤُهُمْ" متفقٌ عليه.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 164, text: 'وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم نهى أن ينتعل الرجل قائمًا".', narrator: 'جابر رضي الله عنه', grade: 'HASAN', topic: 'الأمور المنهي عنها', source: 'رواه أبو داود بإسناد حسن' },
  { id: 165, text: 'وعن أسيد بن أبي أسيد التابعي عن امرأة من المبايعات قالت: كان فيما أخذ علينا رسول الله صلى الله عليه وسلم، في المعروف الذي أخذ علينا أن لا نعصيه فيه: أن لا نخمش وجهًا، ولا ندعو ويلا، ولا نشق جيبًا، وأن لا ننشر شعرًا".', narrator: '', grade: 'HASAN', topic: 'الأمور المنهي عنها', source: 'رواه أبو داود بإسناد حسن' },
  { id: 166, text: 'وعن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "ما من ميت يموت، فيقوم باكيهم، فيقول: واجبلاه، وأسيداه، أو نحو ذلك إلا وكل به ملكان يلهزانه: أهكذا كنت؟!". رواه الترمذي وقال حديث حسن. «اللَّهْزُ»: الدَّفْعُ بِجُمْعِ اليَدِ فِي الصَّدْرِ.', narrator: '', grade: 'SAHIH', topic: 'الأمور المنهي عنها', source: 'رياض الصالحين' },
  { id: 167, text: 'وعن رفاعة بن رافع الزرقي رضي الله عنه قال: جاء جبريل إلى النبي صلى الله عليه وسلم : "إذا أنزل الله تعالى بقوم عذاباً. وعن رفاعة بن رافع الزُّرَقِيِّ - رضي الله عنه - قال: جاء جبريل إلى النبيّ - صلى الله عليه وسلم - قال: مَا تَعُدُّونَ أهْلَ بَدْرٍ فِيكُمْ؟ قال: «مِنْ أفْضَلِ المُسْلِمِينَ» أوْ كَلِمَةً نَحْوَهَا. قال: وَكَذلِكَ مَنْ شَهِدَ بَدْرًا مِنَ المَلائِكَةِ.', narrator: '', grade: 'SAHIH', topic: 'المنثورات والملح', source: 'صحيح البخاري' },
  { id: 168, text: 'وعن ابن عمر رضي الله عنهما قال : قال رسولُ اللهِ : « إذَا أنْزَلَ اللهُ تَعَالَى بِقَومٍ عَذَاباً ، أصَابَ العَذَابُ مَنْ كَانَ فِيهِمْ ، ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ » . متفق عليه .', narrator: 'ابن عمر رضي الله عنه', grade: 'SAHIH', topic: 'المنثورات والملح', source: 'رياض الصالحين' },
  { id: 169, text: 'وعن أبي ثعلبة الخشني جرثوم بن ناشر رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: "إن الله تعالى فرض فرائض فلا تضيعوها، وحد حدوداً فلا تعتدوها، وحرم أشياء فلا تنتهكوها، وسكت عن أشياء رحمة لكم غير نسيان فلا تبحثوا عنها". حديث حسن. رواه الدارقطني وغيره.', narrator: '', grade: 'SAHIH', topic: 'المنثورات والملح', source: 'رياض الصالحين' },
  { id: 170, text: 'وعنه رضي الله عنه : {كنتم خير أمة أخرجت للناس} قال: خير الناس للناس يأتون بهم في السلاسل في أعناقهم حتى يدخلوا في الإسلام. أخرجه: البخاري.', narrator: '', grade: 'SAHIH', topic: 'المنثورات والملح', source: 'رياض الصالحين' },
  { id: 171, text: 'وعن ابن عباس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : “من لزم الاستغفار ، جعل الله له من كل ضيق مخرجاً ومن كل هم فرجاً، ورزقه من حيث لا يحتسب" رواه أبو داود.', narrator: 'ابن عباس رضي الله عنه', grade: 'SAHIH', topic: 'الاستغفار', source: 'رياض الصالحين' },
  { id: 172, text: 'وعن أنس رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: “قال الله تعالى: يا ابن آدم إنك ما دعوتني ورجوتني غفرت لك ما كان منك ولا أبالي، يا ابن آدم لو بلغت ذنوبك عنان السماء، ثم استغفرتني ، غفرت لك ولا أبالي، يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا، ثم لقيتني لا تشرك بي شيئاً، لأتيتك بقرابها مغفرة" . (2)', narrator: 'أنس رضي الله عنه', grade: 'SAHIH', topic: 'الاستغفار', source: 'رياض الصالحين' },
]
